let economicsRows=[],economicsDuration='all';
function economicsDefinitions(){const defs=productDefinitions().map(p=>({...p,pricing:null}));for(const price of priceDefinitions()){const match=defs.find(p=>p.key===price.key);if(match)match.pricing=price;else defs.push({key:price.key,name:price.name,rows:{},pricing:price});}return defs;}
function economicsRate(p,metric,selected=ids()){if(!p.pricing)return null;if(selected.length===1)return priceValue(p.pricing,metric,selected[0]).value;if(p.rows.volume===undefined)return null;let weighted=0,weight=0;for(const month of selected){const q=val(p.rows.volume,'Actual','income',[month]),rate=priceValue(p.pricing,metric,month).value;if(q===null||q<0||rate===null)return null;weighted+=rate*q;weight+=q;}return weight>0?weighted/weight:null;}
function economicsMeasure(p,selected=ids()){const base=productMeasure(p,selected),sum=metric=>{if(!p.pricing)return null;const values=selected.map(m=>priceValue(p.pricing,metric,m).value);return values.every(Number.isFinite)?values.reduce((a,b)=>a+b,0):null;},pricingOnly=p.rows.gross===undefined&&!!p.pricing,gross=pricingOnly?sum('gross'):base.gross,net=pricingOnly?sum('net'):base.net,selling=base.selling!==null?base.selling:economicsRate(p,'price',selected),cost=economicsRate(p,'cost',selected),company=val(29,'Actual','income',selected);return {...base,gross,net,selling,cost,spread:sub(selling,cost),share:net!==null&&company!==null&&company>0?net/company*100:null,pricingOnly,sourcePrice:economicsRate(p,'price',selected)};}
products=function(){const defs=economicsDefinitions();if(!defs.length)return panel('Product economics','No product data supplied.',empty());if(!defs.some(p=>p.key===productSelection))productSelection=defs[0].key;const choices=[['budget',state.year+' budget'],...availableYears().filter(y=>y!==+state.year).map(y=>[String(y),y+' actual'])];if(!choices.some(([v])=>v===productComparison))productComparison='budget';const comparison=productSpec();economicsRows=defs.map(p=>({...p,a:economicsMeasure(p),b:productMeasure(p,ids(),comparison.year,comparison.type)}));currentProducts=economicsRows;const selected=economicsRows.find(p=>p.key===productSelection),withSales=economicsRows.filter(p=>p.rows.gross!==undefined||p.pricing),known=withSales.filter(p=>p.a.spread!==null),largest=withSales.filter(p=>p.a.net!==null).sort((a,b)=>b.a.net-a.a.net)[0],secondary=withSales.find(p=>/secondary|wastage/i.test(p.name));return `<div class="toolbar">${select('productComparison','Compare gross sales with',choices,productComparison)}</div><div class="cards">${card('Revenue concentration',pct(largest?.a.share),esc(largest?.name||'Unavailable')+' · share of company sales after VAT')}${card('Secondary revenue share',pct(secondary?.a.share),'After VAT; blank when product VAT is missing')}${card('Reported product groups',withSales.length,'Includes separately named pricing products')}${card('Negative indicative spreads',known.length?known.filter(p=>p.a.spread<0).length:'—',known.length+' products with comparable rates')}</div>`+panel('Which products are creating value?',`${esc(period())}. Revenue after product VAT, before dealer commission. Revenue in ${unit()}; price and cost in BDT/kg. Select a product for sources.`,table(['Product','Net revenue','Sales MT','Share of revenue','Selling value/kg','Indicative cost/kg','Indicative spread/kg','Gross comparison achieved'],economicsRows.map((p,i)=>[`<button data-economics-evidence="${i}">${esc(p.name)}${p.a.pricingOnly?' <small>(pricing source)</small>':''}</button>`,money(p.a.net),num(p.a.volume,2),pct(p.a.share),num(p.a.selling,2),num(p.a.cost,2),`<span class="${p.a.spread===null?'':p.a.spread<0?'negative':'positive'}">${num(p.a.spread,2)}</span>`,p.a.gross!==null&&p.b.gross!==null&&p.b.gross>0?pct(p.a.gross/p.b.gross*100):'—'])))+`<p class="source">Indicative cost comes from the supplied Net Sales Price files; its allocation basis is not documented. Spread is a screening signal, not product net profit. Selling value uses income-statement revenue after matched VAT divided by sales kg when available, otherwise the supplied price rate. For YTD, supplied rates are sales-volume weighted only where every selected month has a matched quantity and rate; otherwise they remain blank. Differently named products are kept separate. Pricing-only revenue may overlap other source groups, so these rows are not a consolidated product total.</p><div class="toolbar">${select('productSelection','Product detail',defs.map(p=>[p.key,p.name]),productSelection)}${select('economicsYear','Chart year',availableYears().map(y=>[y,y]),state.year)}${select('economicsDuration','Chart duration',[['all','All supplied months'],['period','Selected reporting period'],['3','Last 3 months'],['6','Last 6 months']],economicsDuration)}</div><div class="grid">${panel(esc(selected.name)+' · selling value and cost','BDT/kg. Gaps show missing rates or sales quantities.',economicsTrend(selected))}${panel(esc(selected.name)+' · production and sales','Production less sales is a flow gap, not a closing-stock balance.',economicsTrend(selected,'volume'))}</div>`+panel('Product review questions',esc(selected.name),table(['Question','Evidence'],[['Does selling value cover indicative cost?',selected.a.spread===null?'Insufficient comparable price/cost data.':selected.a.spread<0?'Negative indicative spread; validate costing and review pricing.':'Positive indicative spread; validate the allocation basis before treating it as profit.'],['Are sales using output or existing stock?',selected.a.flow===null?'—':'Production less sales: '+num(selected.a.flow,2)+' MT'],['What would establish actual product profitability?','Matched material, conversion, rejection, commission and overhead costs by product.'],['Can this be compared with budget?',selected.b.gross===null?'No matched gross-sales comparison supplied.':'Gross sales comparison is shown above. Product cost/margin budgets are not supplied.']]))+panel('Monthly product detail',esc(selected.name)+' · '+period()+'. Select a month to inspect inputs.',table(['Month','Net revenue','Sales MT','Production MT','Selling value/kg','Indicative cost/kg','Spread/kg'],ids().map(m=>{const a=economicsMeasure(selected,[m]);return[`<button data-economics-month="${m}">${periodMonthLabel(m)}</button>`,money(a.net),num(a.volume,2),num(a.production,2),num(a.selling,2),num(a.cost,2),num(a.spread,2)];})))+`<details class="panel"><summary>Pricing source comparison and reconciliation</summary><p>Last selected month: ${periodMonthLabel(ids().at(-1))}. Differences between source schedules are retained.</p>${table(['Pricing product','Pricing gross sales','Matched income gross sales','Difference'],priceDefinitions().map(p=>{const match=defs.find(x=>x.key===p.key),a=priceValue(p,'gross').value,b=match?productMeasure(match,[ids().at(-1)]).gross:null;return[esc(p.name),money(a),money(b),money(sub(a,b))];}))}</details>`;};
function economicsMonths(){const supplied=[...new Set([...records.income.filter(x=>x.year===+state.year&&x.type==='Actual'&&x.value!==null).map(x=>x.month),...Object.entries(pricingBook()?.cells||{}).filter(([a])=>/^[A-Z]+1$/.test(a)).map(([,v])=>parsePeriod(v)).filter(d=>d?.year===+state.year).map(d=>d.month)])].sort((a,b)=>a-b);if(economicsDuration==='period')return ids();if(economicsDuration==='all')return supplied;const last=supplied.at(-1);return last===undefined?[]:Array.from({length:Math.min(+economicsDuration,last+1)},(_,i)=>Math.max(0,last-(+economicsDuration)+1)+i);}
function economicsTrend(p,kind='price'){const ms=economicsMonths(),points=ms.map(month=>({month,...economicsMeasure(p,[month])})),series=kind==='volume'?[['production','Production','#087f8c'],['volume','Sales','#31546b']]:[['selling','Selling value','#087f8c'],['cost','Indicative cost','#bd4655']],units=kind==='volume'?'MT':'BDT/kg',values=points.flatMap(p=>series.map(([k])=>p[k])).filter(Number.isFinite);if(!values.length)return empty('No values supplied for this duration','Missing inputs remain blank.');const w=650,h=260,l=65,t=25,b=40,lo=Math.min(0,...values),hi=Math.max(1,...values),y=v=>t+(hi-v)/(hi-lo)*(h-t-b),x=i=>l+i*(w-l-20)/Math.max(ms.length-1,1),step=(w-l-20)/Math.max(ms.length-1,1);return `<svg viewBox="0 0 ${w} ${h}" role="group" aria-label="${esc(p.name)} monthly ${kind==='volume'?'production and sales':'selling value and indicative cost'}">${[0,.5,1].map(f=>`<text x="${l-7}" y="${y(lo+(hi-lo)*f)+4}" text-anchor="end" font-size="10">${num(lo+(hi-lo)*f,1)}</text>`).join('')}${series.map(([k,n,c])=>points.map((p,i)=>p[k]===null?'':`${i&&points[i-1][k]!==null?`<line x1="${x(i-1)}" y1="${y(points[i-1][k])}" x2="${x(i)}" y2="${y(p[k])}" stroke="${c}" stroke-width="2"/>`:''}<circle cx="${x(i)}" cy="${y(p[k])}" r="4" fill="${c}"/>`).join('')).join('')}${ms.map((m,i)=>`<text x="${x(i)}" y="${h-13}" text-anchor="middle" font-size="10">${months[m]}</text>`).join('')}${points.map((d,i)=>{const label=p.name+' · '+months[d.month]+' '+state.year+'\n'+series.map(([k,n])=>n+': '+num(d[k],2)+' '+units).join('\n')+(kind==='price'?'\nIndicative spread: '+num(d.spread,2)+' BDT/kg':'\nProduction less sales: '+num(d.flow,2)+' MT');return `<rect x="${Math.max(l-12,x(i)-step/2)}" y="${t-10}" width="${ms.length===1?w-l:Math.min(w-10,x(i)+step/2)-Math.max(l-12,x(i)-step/2)}" height="${h-t-b+20}" fill="transparent" data-economics-chart="${d.month}" data-chart-tip="${esc(label)}" tabindex="0" role="button" aria-label="${esc(label)}; select for source cells" style="cursor:pointer"/>`;}).join('')}</svg><p class="source">${series.map(([,n])=>n).join(' · ')} (${units}). ${months[ms[0]]}–${months[ms.at(-1)]} ${state.year}. Hover or focus a month for values; select for source cells.</p>`;}
function economicsEvidence(p,selected=ids()){productEvidence(p,selected);if(p.pricing){const rows=[];for(const month of selected)for(const metric of Object.keys(p.pricing.rows)){const v=priceValue(p.pricing,metric,month);rows.push([periodMonthLabel(month),metric,v.cell||'—',num(v.value,4)]);}$('evidenceBody').innerHTML+=`<h3>Net Sales Price source</h3><p>${esc(pricingBook().name)} · ${esc(pricingBook().sheet)}</p><p>Amounts are BDT; price and cost rates are BDT/kg. Multi-month rates use sum(monthly rate × matched sales MT) / sum(matched sales MT); any missing rate or quantity leaves the result blank.</p>${table(['Period','Measure','Cell','Value'],rows)}`;}}
const referenceEconomicsBind=bind;bind=function(){referenceEconomicsBind();if(state.view!=='products')return;document.querySelectorAll('[data-economics-evidence]').forEach(e=>e.onclick=()=>economicsEvidence(economicsRows[+e.dataset.economicsEvidence]));document.querySelectorAll('[data-economics-month],[data-economics-chart]').forEach(e=>{const show=()=>economicsEvidence(economicsRows.find(p=>p.key===productSelection),[+(e.dataset.economicsMonth??e.dataset.economicsChart)]);e.onclick=show;e.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();show();}};});$('export').onclick=()=>{const rows=[['SBU',portfolio.sbus[activeSbu].name],['Period',period()],['Product','Net revenue BDT','Sales MT','Production MT','Selling value BDT/kg','Indicative cost BDT/kg','Spread BDT/kg','Revenue basis'],...economicsRows.map(p=>[p.name,p.a.net,p.a.volume,p.a.production,p.a.selling,p.a.cost,p.a.spread,p.a.pricingOnly?'Net Sales Price':'Income statement'])],u=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='Product_Economics_'+state.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};};

const tooltipEconomicsBind=bind;bind=function(){tooltipEconomicsBind();document.getElementById('economicsTooltip')?.remove();if(state.view!=='products')return;$('economicsDuration').onchange=e=>{economicsDuration=e.target.value;render();};$('economicsYear').onchange=e=>{state.year=+e.target.value;render();};const tip=document.createElement('div');tip.id='economicsTooltip';tip.setAttribute('role','tooltip');tip.hidden=true;tip.style.cssText='position:fixed;z-index:10000;pointer-events:none;white-space:pre-line;background:#173344;color:white;padding:12px 16px;border-radius:8px;box-shadow:0 4px 18px #0003;font-size:13px;line-height:1.7;max-width:calc(100vw - 24px)';document.body.appendChild(tip);document.querySelectorAll('[data-chart-tip]').forEach(e=>{const show=event=>{tip.textContent=e.dataset.chartTip;tip.hidden=false;const r=e.getBoundingClientRect(),px=event.clientX??r.left+r.width/2,py=event.clientY??r.top;tip.style.left=Math.max(12,Math.min(px+14,window.innerWidth-tip.offsetWidth-12))+'px';tip.style.top=Math.max(12,Math.min(py+14,window.innerHeight-tip.offsetHeight-12))+'px';e.setAttribute('aria-describedby',tip.id);};e.onpointerenter=show;e.onpointermove=show;e.onfocus=show;e.onpointerleave=()=>{tip.hidden=true;};e.onblur=()=>{tip.hidden=true;};const click=e.onclick;e.onclick=event=>{tip.hidden=true;click?.(event);};const key=e.onkeydown;e.onkeydown=event=>{if(event.key==='Escape')tip.hidden=true;else key?.(event);};});};
